import {readFile} from 'node:fs/promises';
import {readCalendar,dateKey,localDay,changeCalendar,dueTasks,reference} from './model.mjs';
import {calendarView} from './view.mjs';
export async function activate(api){
 if(!['panel-view-v1','document-context','app-reminders'].every(c=>api.capabilities?.includes(c)))throw Error('日历插件需要新的动态面板、文档跳转和提醒接口，请先更新软件本体；原资料不会改变');
 const css=await readFile(new URL('./style.css',import.meta.url),'utf8');let queue=Promise.resolve(),visible=new Set();
 const serial=fn=>{const result=queue.catch(()=>{}).then(fn);queue=result;return result;},read=async()=>readCalendar(await api.storage.read('calendar'));
 async function notices(state=undefined){state??=await read();const due=dueTasks(state),next=new Set(due.map(t=>t.id));for(const id of visible)if(!next.has(id))api.ui.dismissNotice(id);for(const t of due.slice(0,90))api.ui.registerNotice({id:t.id,title:'日历待办提醒',body:t.date+' · '+t.title,actions:[{label:'稍后10分钟',commandId:'remind',arguments:{taskId:t.id,remindAt:t.remindAt,action:'snooze'}},{label:'已知晓',commandId:'remind',arguments:{taskId:t.id,remindAt:t.remindAt,action:'ack'}}]});visible=new Set(due.slice(0,90).map(t=>t.id));}
 async function render(context,extra={}){
  const args=context.arguments||{},state=await read(),date=dateKey(args.date||localDay()),notebooks=await api.documents.notebooks(),notebookId=args.notebookId||context.notebookId||notebooks[0]?.id;
  if(!notebooks.some(n=>n.id===notebookId))throw Error('所选笔记本已不存在，请重新打开日历');
  const {documents}=await api.documents.context(notebookId),linked=[];
  for(const ref of state.days[date]?.links||[]){try{const {document}=await api.documents.read(ref.notebookId,ref.documentId);linked.push({...ref,title:document.title,notebookName:notebooks.find(n=>n.id===ref.notebookId)?.name});}catch{linked.push({...ref,missing:true});}}
  return {revision:state.revision,pluginView:{html:calendarView({state,date,notebookId,notebooks,documents,linked,css,editing:args.editing,adding:args.adding,message:extra.message}),...(extra.openDocument?{openDocument:extra.openDocument}:{})}};
 }
 const register=(id,name,handler,readOnly=true)=>api.commands.register({id,name,readOnly},context=>serial(()=>handler(context)));
 const conversation=(id,name,properties,required,handler)=>api.commands.register({id,name,conversation:{description:name,inputSchema:{type:'object',properties,required,additionalProperties:false}}},context=>serial(()=>handler(context)));
 const dateSchema={type:'string',maxLength:10},revisionSchema={type:'integer',minimum:0};
 conversation('conversation-read','读取指定日期的待办与日记关联',{date:dateSchema},['date'],async context=>{const date=dateKey(context.arguments.date),state=await read();return {revision:state.revision,date,tasks:state.tasks.filter(t=>t.date===date&&!t.deletedAt),day:state.days[date]||{links:[],diary:null}};});
 conversation('conversation-add','新增待办（先读取日历版本）',{date:dateSchema,title:{type:'string',maxLength:180},revision:revisionSchema,remindLocal:{type:'string',maxLength:16}},['date','title','revision'],async context=>{const next=changeCalendar(await read(),'add',context.arguments,{id:context.operationId});await api.storage.write('calendar',next);await notices(next);return {saved:true,revision:next.revision,task:next.tasks.find(t=>t.id===context.operationId)};});
 conversation('conversation-complete','将指定待办标为完成（不反向切换）',{date:dateSchema,taskId:{type:'string',maxLength:80},revision:revisionSchema},['date','taskId','revision'],async context=>{const state=await read(),task=state.tasks.find(t=>t.id===context.arguments.taskId&&!t.deletedAt);if(!task||task.date!==context.arguments.date)throw Error('待办不存在或日期不匹配');if(task.done)return {saved:true,unchanged:true,revision:state.revision};const next=changeCalendar(state,'toggle',context.arguments);await api.storage.write('calendar',next);await notices(next);return {saved:true,revision:next.revision};});
 register('view','查看日历',context=>render(context));
 register('change','修改日历待办',async context=>{
  const args={...context.arguments},state=await read();if(['link','diary','unlink'].includes(args.action)){args.ref=reference(args.ref||{notebookId:args.notebookId,documentId:args.documentId});if(args.action!=='unlink')await api.documents.read(args.ref.notebookId,args.ref.documentId);}
  const next=changeCalendar(state,args.action,args,{id:args.taskId});await api.storage.write('calendar',next);await notices(next);return render({...context,arguments:{...args,editing:''}},{message:'已保存'});
 });
 register('link-current','关联当前文档',async context=>{if(!context.documentId)throw Error('请先打开要关联的文档');const args=context.arguments||{},ref=reference({notebookId:context.notebookId,documentId:context.documentId});await api.documents.read(ref.notebookId,ref.documentId);const next=changeCalendar(await read(),'link',{...args,ref});await api.storage.write('calendar',next);return render(context,{message:'已关联当前文档'});});
 async function open(context,ref){ref=reference(ref);await api.documents.read(ref.notebookId,ref.documentId);return render(context,{openDocument:ref});}
 register('open-document','打开关联文档',context=>open(context,context.arguments?.ref));
 register('open-day','打开当天日记',async context=>{const date=dateKey(context.arguments?.date||localDay()),day=(await read()).days[date],ref=day?.diary||(day?.links?.length===1?day.links[0]:null);return ref?open(context,ref):render(context,{message:day?.links?.length?'这一天关联了多篇文档，请选择打开或设定日记':'这一天尚未关联文档，请右键日期新建文档'});});
 register('create-diary','创建当天日记',async context=>{
  const args=context.arguments||{},date=dateKey(args.date),state=await read(),old=state.days[date]?.diary;if(old)return open(context,old);
  if(Number(args.revision)!==state.revision)throw Error('日历已更新，请刷新后创建');
  const notebookId=args.notebookId||context.notebookId,live=await api.documents.context(notebookId),document={title:date+' 日记',markdown:'# '+date+'\n\n',coreCalendarDate:date};
  const result=await api.documents.create({notebookId,expectedStateStamp:live.stateStamp,document,operationId:'calendar-diary-'+notebookId+'-'+date}),ref={notebookId,documentId:result.documentId};
  await api.documents.read(notebookId,ref.documentId);await api.storage.write('calendar',changeCalendar(state,'diary',{...args,ref}));return open(context,ref);
 },false);
 register('remind','处理待办提醒',async context=>{const args=context.arguments||{},state=await read(),task=state.tasks.find(t=>t.id===args.taskId&&!t.deletedAt&&!t.done);if(!task||task.remindAt!==args.remindAt){await notices(state);throw Error('待办或提醒时间已更新，请按最新提醒处理');}if(args.action==='ack')task.acknowledgedAt=new Date().toISOString();else if(args.action==='snooze'){task.remindAt=new Date(Date.now()+600000).toISOString();task.acknowledgedAt='';}else throw Error('未知提醒操作');state.revision++;await api.storage.write('calendar',state);await notices(state);return {saved:true};});
 api.ui.registerPanel({id:'calendar',title:'日历与待办',html:'<div data-plugin-init="view"><p>正在读取日历…</p><p data-plugin-result role="status"></p></div>'});
 // The dock tab already names the calendar; retain its accessible name without a duplicate heading row.
 api.ui.registerStyle({id:'calendar-header',css:'.extension-panel[data-plugin-panel="thirdparty.calendar:calendar"]>.official-panel-head{display:none}'});
 await notices();const timer=setInterval(()=>void serial(()=>notices()).catch(()=>{}),15000);timer.unref?.();
 return ()=>clearInterval(timer);
}

