import {randomUUID} from 'node:crypto';
import {localDay,monthDays,shiftMonth,sameRef} from './model.mjs';
const h=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const localTime=value=>{if(!value)return '';const d=new Date(value);return localDay(d)+'T'+String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0');};
export function calendarView({state,date,notebookId,notebooks,documents,linked=[],css,editing='',adding=false,message=''}){
 const base={date,revision:state.revision,notebookId},attrs=(command,args={},extra='')=>`type="button" data-command="${command}" data-arguments="${h(JSON.stringify({...base,...args}))}" ${extra}`;
 const button=(label,command,args={},extra='')=>`<button ${attrs(command,args,extra)}>${h(label)}</button>`;
 const tasks=state.tasks.filter(t=>t.date===date&&!t.deletedAt),edit=tasks.find(t=>t.id===editing),today=localDay(),day=state.days[date],pending=tasks.filter(t=>!t.done).length;
 const field=(name,value)=>`<input type="hidden" name="${name}" value="${h(value)}">`,fields=()=>field('date',date)+field('revision',state.revision)+field('notebookId',notebookId);
 const days=monthDays(date).map(d=>{const count=state.tasks.filter(t=>t.date===d&&!t.done&&!t.deletedAt).length,links=state.days[d]?.links?.length||0;return `<button ${attrs('view',{date:d},`data-double-command="open-day" data-context-command="create-diary" data-context-label="新建当天文档" data-context-confirm="在选中的笔记本新建当天文档并关联？已有内容不会覆盖。" aria-label="${d}${links?'，有关联文档':''}${count?'，'+count+'条待办':''}" aria-pressed="${d===date}"`)} class="day ${d.slice(0,7)!==date.slice(0,7)?'outside':''} ${d===today?'today':''}"><span>${Number(d.slice(-2))}</span><small>${links?'●':''}${count?'<i>'+count+'</i>':''}</small></button>`;}).join('');
 const monthHeader=`<div class="month-head"><strong class="month-title"><span class="month-year">${Number(date.slice(0,4))}</span><span class="month-unit">年</span> <span>${Number(date.slice(5,7))}</span><span class="month-unit">月</span></strong><nav class="month-nav" aria-label="切换月份"><button ${attrs('view',{date:shiftMonth(date,-1)},'aria-label="上个月" title="上个月"')}><svg viewBox="0 0 16 16" aria-hidden="true"><path d="m10 3-5 5 5 5"/></svg></button>${button('今天','view',{date:today},'data-calendar-today aria-label="回到今天"')}<button ${attrs('view',{date:shiftMonth(date,1)},'aria-label="下个月" title="下个月"')}><svg viewBox="0 0 16 16" aria-hidden="true"><path d="m6 3 5 5-5 5"/></svg></button></nav></div>`;
 return `<div class="calendar-plugin"><style>${css}</style>${monthHeader}<div class="weekdays">${['一','二','三','四','五','六','日'].map(d=>'<span>'+d+'</span>').join('')}</div><div class="month-grid">${days}</div><p class="legend">● 关联文档　数字：未完成待办　双击打开关联文档 · 右键新建文档</p><section class="agenda"><header><div><small>所选日期</small><h3>${h(date)} <span>${pending} 项待办</span></h3></div>${button('刷新','view')}</header><p data-plugin-result role="status">${h(message)}</p><div class="tasks">${tasks.length?tasks.map(t=>`<article class="task ${t.done?'done':''}">${button(t.done?'✓':'○','change',{action:'toggle',taskId:t.id},`aria-pressed="${t.done}" aria-label="${t.done?'恢复待办':'完成待办'}：${h(t.title)}"`)}<div><b>${h(t.title)}</b><small>${t.remindAt?'提醒 '+h(localTime(t.remindAt).replace('T',' '))+(t.acknowledgedAt?' · 已知晓':!t.done&&Date.parse(t.remindAt)<=Date.now()?' · 已到期':''):'未设置提醒'}</small></div>${button('编辑','view',{editing:t.id})}${button('删除','change',{action:'remove',taskId:t.id},'data-confirm="删除此待办？文档不会删除，待办记录保留在插件资料中。"')}</article>`).join(''):'<p class="empty">这一天还没有待办，给自己留一件要做的事。</p>'}</div>${!edit&&!adding?button('＋ 新增待办事项','view',{adding:true},'class="add-task"'):''}${edit||adding?`<form class="task-form">${fields()}${field('action',edit?'edit':'add')}${field('taskId',edit?.id||randomUUID())}<label>${edit?'编辑待办':'新增待办'}<input name="title" aria-label="待办内容" required maxlength="180" placeholder="例如：整理今天的日记" value="${h(edit?.title||'')}"></label><label>提醒时间（本机时区，可不填）<input type="datetime-local" name="remindLocal" aria-label="提醒时间" value="${h(localTime(edit?.remindAt))}"></label><button type="submit" data-command="change">${edit?'保存修改':'添加待办'}</button>${button('取消','view')}</form>`:''}</section>
 <details class="documents" data-plugin-disclosure="calendar-documents" open><summary title="展开或收起日期关联文档"><svg class="disclosure-icon" width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="m6 3 5 5-5 5"/></svg><span>日期关联文档</span><small aria-hidden="true"><span class="when-open">收起</span><span class="when-closed">展开</span></small></summary>${linked.length?linked.map(ref=>`<div class="document-row"><div>${ref.missing?'<span class="missing">文档已移除或不可读取</span>':button(ref.title,'open-document',{ref})}<small>${h(ref.notebookName||ref.notebookId)}${sameRef(day?.diary,ref)?' · 日记':''}</small></div>${!ref.missing&&!sameRef(day?.diary,ref)?button('设为日记','change',{action:'diary',ref}):''}${button('解除关联','change',{action:'unlink',ref})}</div>`).join(''):'<p class="empty">关联日记、会议纪要或与这一天有关的文档。</p>'}<form class="link-form">${field('date',date)}<label>笔记本<select name="notebookId" aria-label="关联笔记本">${notebooks.map(n=>`<option value="${h(n.id)}" ${n.id===notebookId?'selected':''}>${h(n.name)}</option>`).join('')}</select></label><button type="submit" data-command="view">切换</button></form><form class="link-form">${fields()}${field('action','link')}<select name="documentId" aria-label="选择关联文档">${documents.map(d=>`<option value="${h(d.documentId)}">${h(d.title)}</option>`).join('')}</select><button type="submit" data-command="change" ${documents.length?'':'disabled'}>关联</button></form><div class="document-actions">${button('关联当前文档','link-current')}${day?.diary?button('打开日记','open-day'):''}</div></details><footer>提醒仅在软件运行且插件启用时显示；重新打开后会补提示未处理的到期事项。完全退出后不发送系统通知。</footer></div>`;
}

files.style.css:
.calendar-plugin{--calendar-mark:var(--sky-mark,light-dark(#008ada,#62c9ff));--calendar-text:var(--sky-text,light-dark(#0072c3,#62c9ff));max-width:560px;margin:auto;color:var(--text)}
.calendar-plugin *{box-sizing:border-box}
.calendar-plugin button{color:inherit;background:transparent;border:0;border-radius:5px;padding:5px 9px;white-space:nowrap;box-shadow:none}
.calendar-plugin button:hover:not(:disabled){background:color-mix(in srgb,var(--text) 6%,var(--bg))}
.calendar-plugin button:focus-visible,.calendar-plugin input:focus,.calendar-plugin select:focus{outline:2px solid var(--accent);outline-offset:2px}
.calendar-plugin button:disabled{opacity:.5;cursor:default}
.month-head{display:flex;align-items:center;justify-content:space-between;gap:8px;min-height:36px;margin-bottom:12px}
.month-head .month-title{display:flex;align-items:baseline;gap:4px;text-align:left;font-size:23px;font-weight:500;white-space:nowrap;line-height:1.3;font-variant-numeric:tabular-nums}
.month-year{color:var(--calendar-mark);font-weight:650}
.month-title .month-unit{font-size:13px;color:var(--muted);margin-right:4px}
.month-nav{display:flex;align-items:center;gap:2px;flex:none}
.month-nav button{display:grid;place-items:center;min-width:28px;height:30px;padding:4px;color:var(--muted);font-size:11px;font-weight:600}
.month-nav [data-calendar-today]{padding-inline:7px}
.month-nav svg{width:15px;height:15px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.weekdays,.month-grid{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));column-gap:3px;row-gap:2px}
.weekdays span{text-align:center;font-size:11px;color:var(--muted);padding:3px 0 8px}
.month-grid .day{position:relative;display:flex;align-items:center;justify-content:center;min-height:32px;padding:0 0 5px;gap:0;font-variant-numeric:tabular-nums}
.day>span{font-size:13px;line-height:20px}
.day small{position:absolute;bottom:1px;height:9px;line-height:9px;font-size:6px;display:flex;align-items:center;gap:3px;color:var(--accent)}
.day small i{font-size:8px;font-style:normal}
.day.today>span{font-weight:750;color:var(--calendar-text)}
.day.outside{color:var(--muted)}
.month-grid .day[aria-pressed=true]{background:color-mix(in srgb,var(--text) 6%,var(--bg))}
.legend{font-size:10px;color:var(--muted);margin:10px 0 16px;line-height:1.7}
.agenda,.documents{border-top:1px solid var(--line);padding-top:14px;margin-top:16px}
.calendar-plugin header{display:flex;align-items:center;justify-content:space-between}
.calendar-plugin h3{font-size:14px;margin:0 0 10px}
.calendar-plugin h3 span{font-size:11px;font-weight:400;color:var(--muted);margin-left:6px}
.calendar-plugin header small{font-size:10px;color:var(--muted)}
.agenda header>button{font-size:11px;color:var(--muted)}
.calendar-plugin [data-plugin-result]:empty{display:none}
.calendar-plugin [data-plugin-result]{color:var(--accent);font-size:12px}
.task{display:flex;align-items:flex-start;gap:5px;padding:10px 0;border-bottom:1px solid color-mix(in srgb,var(--line) 60%,transparent)}
.task>div{flex:1;min-width:0}
.task b{font-size:13px;font-weight:500;overflow-wrap:anywhere}
.task small,.document-row small{display:block;color:var(--muted);font-size:10px;margin-top:3px}
.task>button{font-size:10px;padding:3px;color:var(--muted)}
.task>button:first-child{font-size:17px;color:var(--calendar-mark);padding-top:0}
.task.done b{text-decoration:line-through;color:var(--muted)}
.calendar-plugin .add-task{display:block;width:100%;margin-top:8px;padding:9px 2px;text-align:left;color:var(--calendar-text);font-size:12px}
.task-form{margin:14px 0;display:flex;flex-wrap:wrap;gap:8px}
.calendar-plugin label{display:grid;gap:5px;font-size:11px;color:var(--muted);min-width:0}
.task-form label{width:100%}
.calendar-plugin input,.calendar-plugin select{width:100%;border:1px solid var(--line);background:var(--bg);color:var(--text);padding:8px;border-radius:7px;min-width:0;font-size:12px}
.task-form button[type=submit]{color:var(--calendar-text);font-size:12px;font-weight:600}
.empty{font-size:12px;color:var(--muted);line-height:1.8}
.document-row{display:flex;align-items:center;gap:4px;margin:8px 0}
.document-row>div{flex:1;min-width:0}
.document-row>div>button{max-width:100%;white-space:normal;text-align:left;overflow-wrap:anywhere;padding:0;color:var(--accent);font-size:12px}
.document-row>button{font-size:10px;padding:2px}
.missing{font-size:12px;color:var(--muted)}
.link-form{display:flex;align-items:flex-end;gap:6px;margin:10px 0}
.link-form label,.link-form select{flex:1}
.link-form button,.document-actions button{font-size:11px}
.document-actions{display:flex;flex-wrap:wrap;gap:8px}
.calendar-plugin footer{margin-top:20px;padding-top:12px;border-top:1px solid var(--line);color:var(--muted);font-size:10px;line-height:1.8}
.calendar-plugin .documents>summary{display:flex;align-items:center;gap:6px;list-style:none;cursor:pointer;border-radius:5px;padding:5px 3px;margin-bottom:10px;font-size:14px;font-weight:600}
.calendar-plugin .documents>summary::-webkit-details-marker{display:none}
.calendar-plugin .documents>summary:hover{background:var(--surface)}
.calendar-plugin .documents>summary:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.documents>summary small{font-size:11px;font-weight:400;color:var(--muted)}
.documents .disclosure-icon{flex-shrink:0}
.documents[open] .disclosure-icon{transform:rotate(90deg)}
.documents[open] .when-closed,.documents:not([open]) .when-open{display:none}
@media(max-width:320px){.month-head .month-title{font-size:21px;gap:3px}.month-title .month-unit{margin-right:1px}.month-nav{gap:0}}
